package com.bank.weakness;

import com.bank.weakness.model.WeaknessPlan;
import com.bank.weakness.service.ImprovementCoach;
import java.util.List;
import java.util.logging.*;

// Runnable demo: evaluate a "biggest weakness" answer for honesty and an improvement plan.
public class WeaknessDemo {
    private static final Logger log = Logger.getLogger("Weakness");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        ImprovementCoach coach = new ImprovementCoach(log);

        // Fake weakness (disguised strength) — rejected.
        WeaknessPlan fake = new WeaknessPlan(
            "I am a perfectionist", false, List.of(), 0);
        coach.evaluate(fake);

        // Genuine weakness, but no plan — incomplete.
        WeaknessPlan noPlan = new WeaknessPlan(
            "I delegate too late because I want to fix things myself", true, List.of(), 0);
        coach.evaluate(noPlan);

        // Genuine weakness with a concrete, working plan.
        WeaknessPlan solid = new WeaknessPlan(
            "I delegate too late because I want to fix things myself",
            true,
            List.of("Assign sub-task owners at kickoff",
                    "Review instead of taking over",
                    "Track delegated vs self-done tasks each sprint"),
            70);   // 70% progress — the fix is clearly underway
        coach.evaluate(solid);
    }
}
