package com.bank.weakness.model;

import java.util.List;

// Models a weakness like a flagged risk with an attached improvement plan.
public class WeaknessPlan {
    private final String weakness;
    private final boolean genuine;        // true = real; false = disguised strength
    private final List<String> actions;   // concrete improvement steps
    private final int progressPercent;    // evidence the fix is working

    public WeaknessPlan(String weakness, boolean genuine,
                        List<String> actions, int progressPercent) {
        this.weakness = weakness;
        this.genuine = genuine;
        this.actions = actions;
        this.progressPercent = progressPercent;
    }

    public String getWeakness() { return weakness; }
    public boolean isGenuine() { return genuine; }
    public List<String> getActions() { return actions; }
    public int getProgressPercent() { return progressPercent; }

    public boolean hasPlan() { return actions != null && !actions.isEmpty(); }
}
